const browserName = "firefox";

console.log(browserName === "firefox");     // true
console.log(browserName === "chromium");    // false

// A boolean is just a value. It can live in a variable.
const isFirefox = browserName === "firefox";
console.log("isFirefox:", isFirefox, "| type:", typeof isFirefox);

// Why === and not ==
console.log("0 == '' :", 0 == "");          // true  <- surprising
console.log("0 === '':", 0 === "");         // false <- what you meant

// A stand-in for test.skip, so the mechanics are visible
function skipIf(condition: boolean, reason: string): string {
  return condition ? `SKIPPED — ${reason}` : "running";
}

for (const engine of ["chromium", "firefox", "webkit"]) {
  console.log(`${engine.padEnd(10)} ${skipIf(engine === "firefox", "BUG-1508")}`);
}

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week3/generated/day4-skipping.spec.ts", `// Week 3, Day 4 — skipping tests on purpose.
//
// Note what is NOT in this file: test.only. A committed \`.only\` filters the whole
// run, not just its own file — measured on this repo, one stray \`.only\` cut 40
// tests down to 1. Day 4.2 shows how to use it safely, by hand.
//
// Runs under the root config (chromium only) and under the multi-browser config:
//   npx playwright test week3/generated/day4-skipping.spec.ts
//   npx playwright test -c week3/generated/day4-browsers.config.ts
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Skipping", () => {
  test("a normal test, for contrast", async ({ page }) => {
    await loginAs(page);
    await expect(page.getByText("Leela")).toBeVisible();
  });

  test("unconditionally skipped while a defect is open", async ({ page }) => {
    // Reads as documentation: what is broken, and when this comes back.
    test.skip(true, "BUG-1421: balance renders stale after logout. Remove when fixed.");

    // Still written, still compiled, still reviewed — just not run. That is the
    // whole advantage over commenting the body out, where it rots unnoticed.
    await loginAs(page);
    await expect(page.getByText("Account Balance", { exact: true })).toBeVisible();
  });

  test.fixme("fixme — the older name for the same idea", async ({ page }) => {
    // \`fixme\` predates \`skip\`. Both stop the test; \`skip\` won because it reads
    // better at the call site. Kept for the many suites already using it.
    await loginAs(page);
    await expect(page.getByText("nothing matches this")).toBeVisible();
  });

  test("conditionally skipped — Firefox only", async ({ page, browserName }) => {
    // The real workhorse. One browser has a defect; the test still covers the
    // other two rather than being switched off everywhere.
    test.skip(browserName === "firefox", "BUG-1508: Firefox mis-renders the tile grid.");

    await loginAs(page);
    await expect(page.getByText("Pay Bills", { exact: true })).toBeVisible();
  });

  test("conditionally skipped — WebKit only", async ({ page, browserName }) => {
    test.skip(browserName === "webkit", "BUG-1509: WebKit drops the payee dropdown.");

    await loginAs(page);
    await expect(page.getByText("Add Payee", { exact: true })).toBeVisible();
  });
});
`);

await runSpec("week3/generated/day4-skipping.spec.ts");

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 3 Day 1.1.

await writeProjectFile("week3/generated/day4-browsers.config.ts", `// Week 3, Days 4-5 — a config with more than one browser.
//
// The root playwright.config.ts deliberately enables Chromium only. Conditional
// skipping needs several browsers to be worth anything, so this file adds them
// without touching the shared config every other week depends on.
//
// Run with:  npx playwright test -c week3/generated/day4-browsers.config.ts
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day4-*.spec.ts", "day5-*.spec.ts"],
  fullyParallel: true,
  // 3 projects x a handful of tests: parallelism is what keeps this quick.
  workers: 3,
  reporter: [["list"]],
  use: {
    baseURL: "https://test-automation-banking.vercel.app",
    trace: "retain-on-failure",
  },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
    { name: "firefox", use: { ...devices["Desktop Firefox"] } },
    { name: "webkit", use: { ...devices["Desktop Safari"] } },
  ],
});
`);

