// A skip reason is data. If you write it consistently, you can audit it.
type Skip = { test: string; ticket: string; scope: string; addedDays: number };

const skips: Skip[] = [
  { test: "stale balance after logout", ticket: "BUG-1421", scope: "all",     addedDays: 12 },
  { test: "tile grid layout",           ticket: "BUG-1508", scope: "firefox", addedDays: 40 },
  { test: "payee dropdown",             ticket: "BUG-1509", scope: "webkit",  addedDays: 400 },
];

for (const s of skips) {
  const flag = s.addedDays > 90 ? "  <-- older than 90 days, chase it" : "";
  console.log(`${s.ticket}  ${String(s.addedDays).padStart(4)}d  ${s.scope.padEnd(8)} ${s.test}${flag}`);
}
